//! OR-Tools CP-SAT implementation of the selector backend contract.
//!
//! The Rust side owns the backend-neutral `CompiledSelectorProblem`; the C++
//! sidecar owns OR-Tools. Both sides share `selector_cp_sat.proto`, with Rust
//! bindings generated by `rules_rust`/Prost.

use std::collections::BTreeMap;
use std::error::Error;
use std::fmt;
use std::fs;
use std::hash::{Hash, Hasher};
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, ExitStatus, Stdio};
use std::sync::atomic::{AtomicUsize, Ordering};

use prost::Message;
use selector_constraint_backend::{
    AllDifferentReason, BinaryConstraintKind, ConstraintVariableId, TargetBindingProjection,
};
use selector_constraint_backend::{
    BackendAssignment, BackendAssignmentCoverage, BackendSolveResult, BackendSolveStatus,
    BackendValueId, BackendVariableAssignment, CompiledAllDifferentConstraint,
    CompiledAllowedTupleConstraint, CompiledBinaryConstraint, CompiledLinearConstraint,
    CompiledSelectorProblem, CompiledVariable, CompiledVariableDomain, SelectorProblemBackend,
    TargetProjection,
};
use selector_cp_sat_proto::ducktape::debundle::solver_backends::ortools_cpsat as wire;
use selector_ir::VariableDomain;

const REQUEST_PROTO_ENV: &str = "DUCKTAPE_DEBUNDLE_ORTOOLS_CPSAT_REQUEST_PROTO";
const SUMMARY_JSON_ENV: &str = "DUCKTAPE_DEBUNDLE_ORTOOLS_CPSAT_SUMMARY_JSON";
const REQUEST_PROTO_DIR_ENV: &str = "DUCKTAPE_DEBUNDLE_ORTOOLS_CPSAT_REQUEST_PROTO_DIR";
const SUMMARY_JSON_DIR_ENV: &str = "DUCKTAPE_DEBUNDLE_ORTOOLS_CPSAT_SUMMARY_JSON_DIR";
const DUMP_ONLY_ENV: &str = "DUCKTAPE_DEBUNDLE_ORTOOLS_CPSAT_DUMP_ONLY";
const DOMAIN_SHARING_EXACT_SPARSE_LIMIT: usize = 1024;
static DUMP_SEQUENCE: AtomicUsize = AtomicUsize::new(0);

#[derive(Debug, Clone)]
pub struct OrToolsCpSatBackend {
    solver_path: PathBuf,
}

impl OrToolsCpSatBackend {
    pub fn new(solver_path: impl Into<PathBuf>) -> Self {
        Self {
            solver_path: solver_path.into(),
        }
    }

    pub fn solver_path(&self) -> &Path {
        &self.solver_path
    }
}

impl SelectorProblemBackend for OrToolsCpSatBackend {
    type Error = OrToolsCpSatBackendError;

    fn solve(&self, problem: &CompiledSelectorProblem) -> Result<BackendSolveResult, Self::Error> {
        let request = request_from_problem(problem)?;
        let request_bytes = request.encode_to_vec();
        let dumped_request_path = dump_request_if_requested(problem, &request, &request_bytes)?;
        if dump_only_requested() {
            return Err(OrToolsCpSatBackendError::DumpOnly {
                path: dumped_request_path,
            });
        }
        let output = run_sidecar(&self.solver_path, request_bytes.as_slice())?;
        let response = wire::SelectorCpSatResponse::decode(output.as_slice())
            .map_err(OrToolsCpSatBackendError::DecodeResponse)?;
        response_into_backend_result(response)
    }
}

fn run_sidecar(
    solver_path: &Path,
    request_bytes: &[u8],
) -> Result<Vec<u8>, OrToolsCpSatBackendError> {
    let mut child = Command::new(solver_path)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(OrToolsCpSatBackendError::Spawn)?;
    let mut stdin = child
        .stdin
        .take()
        .ok_or(OrToolsCpSatBackendError::MissingChildStdin)?;
    stdin
        .write_all(request_bytes)
        .map_err(OrToolsCpSatBackendError::WriteRequest)?;
    drop(stdin);

    let output = child
        .wait_with_output()
        .map_err(OrToolsCpSatBackendError::Wait)?;
    if !output.status.success() {
        return Err(OrToolsCpSatBackendError::SidecarFailed {
            status: output.status,
            stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
        });
    }
    Ok(output.stdout)
}

#[derive(Debug)]
pub enum OrToolsCpSatBackendError {
    IdOutOfRange {
        field: &'static str,
        value: usize,
    },
    Spawn(io::Error),
    MissingChildStdin,
    WriteRequest(io::Error),
    Wait(io::Error),
    SidecarFailed {
        status: ExitStatus,
        stderr: String,
    },
    DecodeResponse(prost::DecodeError),
    InvalidProblem(String),
    DumpSummaryJson {
        path: PathBuf,
        source: serde_json::Error,
    },
    DumpIo {
        path: PathBuf,
        source: io::Error,
    },
    DumpOnly {
        path: Option<PathBuf>,
    },
    InvalidStatus {
        status: i32,
        diagnostic: Option<String>,
    },
    InvalidAssignmentCoverage {
        coverage: i32,
    },
}

impl fmt::Display for OrToolsCpSatBackendError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::IdOutOfRange { field, value } => {
                write!(
                    f,
                    "CP-SAT protobuf field {field} cannot represent id {value}"
                )
            }
            Self::Spawn(err) => write!(f, "failed to spawn CP-SAT sidecar: {err}"),
            Self::MissingChildStdin => write!(f, "CP-SAT sidecar stdin was unavailable"),
            Self::WriteRequest(err) => write!(f, "failed to write CP-SAT request: {err}"),
            Self::Wait(err) => write!(f, "failed to wait for CP-SAT sidecar: {err}"),
            Self::SidecarFailed { status, stderr } => {
                write!(f, "CP-SAT sidecar exited with {status}: {stderr}")
            }
            Self::DecodeResponse(err) => {
                write!(f, "failed to decode CP-SAT response protobuf: {err}")
            }
            Self::InvalidProblem(message) => write!(f, "invalid CP-SAT request model: {message}"),
            Self::DumpSummaryJson { path, source } => {
                write!(
                    f,
                    "failed to serialize CP-SAT summary JSON at {}: {source}",
                    path.display()
                )
            }
            Self::DumpIo { path, source } => {
                write!(
                    f,
                    "failed to write CP-SAT diagnostic artifact at {}: {source}",
                    path.display()
                )
            }
            Self::DumpOnly { path: Some(path) } => {
                write!(
                    f,
                    "dumped CP-SAT request at {}; stopping before sidecar because {DUMP_ONLY_ENV}=1",
                    path.display()
                )
            }
            Self::DumpOnly { path: None } => {
                write!(
                    f,
                    "{DUMP_ONLY_ENV}=1 requires {REQUEST_PROTO_ENV} or {SUMMARY_JSON_ENV} to point at an output file"
                )
            }
            Self::InvalidStatus { status, diagnostic } => {
                write!(f, "CP-SAT sidecar returned invalid status {status}")?;
                if let Some(diagnostic) = diagnostic {
                    write!(f, ": {diagnostic}")?;
                }
                Ok(())
            }
            Self::InvalidAssignmentCoverage { coverage } => {
                write!(
                    f,
                    "CP-SAT sidecar returned invalid assignment coverage {coverage}"
                )
            }
        }
    }
}

impl Error for OrToolsCpSatBackendError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Spawn(err) | Self::WriteRequest(err) | Self::Wait(err) => Some(err),
            Self::DecodeResponse(err) => Some(err),
            Self::DumpSummaryJson { source, .. } => Some(source),
            Self::DumpIo { source, .. } => Some(source),
            Self::IdOutOfRange { .. }
            | Self::InvalidProblem(_)
            | Self::MissingChildStdin
            | Self::SidecarFailed { .. }
            | Self::DumpOnly { .. }
            | Self::InvalidStatus { .. }
            | Self::InvalidAssignmentCoverage { .. } => None,
        }
    }
}

fn dump_request_if_requested(
    problem: &CompiledSelectorProblem,
    request: &wire::SelectorCpSatRequest,
    request_bytes: &[u8],
) -> Result<Option<PathBuf>, OrToolsCpSatBackendError> {
    let request_proto_path = env_path(REQUEST_PROTO_ENV);
    let summary_json_path = env_path(SUMMARY_JSON_ENV);
    let request_proto_dir = env_path(REQUEST_PROTO_DIR_ENV);
    let summary_json_dir = env_path(SUMMARY_JSON_DIR_ENV);
    if request_proto_path.is_none()
        && summary_json_path.is_none()
        && request_proto_dir.is_none()
        && summary_json_dir.is_none()
    {
        return Ok(None);
    }

    let dump_sequence = (request_proto_dir.is_some() || summary_json_dir.is_some())
        .then(|| DUMP_SEQUENCE.fetch_add(1, Ordering::Relaxed));
    if let Some(path) = &request_proto_path {
        write_request_proto(path, request_bytes)?;
    }
    if let Some(path) = &summary_json_path {
        write_summary_json(path, problem, request, request_bytes.len(), dump_sequence)?;
    }
    if let Some(dir) = &request_proto_dir {
        write_request_proto(
            &dump_dir_path(dir, "selector-cpsat", dump_sequence.unwrap(), "pb"),
            request_bytes,
        )?;
    }
    if let Some(dir) = &summary_json_dir {
        write_summary_json(
            &dump_dir_path(dir, "selector-cpsat", dump_sequence.unwrap(), "json"),
            problem,
            request,
            request_bytes.len(),
            dump_sequence,
        )?;
    }
    Ok(request_proto_path
        .or(summary_json_path)
        .or(request_proto_dir)
        .or(summary_json_dir))
}

fn env_path(env: &str) -> Option<PathBuf> {
    std::env::var_os(env)
        .map(PathBuf::from)
        .filter(|path| !path.as_os_str().is_empty())
}

fn write_request_proto(path: &Path, request_bytes: &[u8]) -> Result<(), OrToolsCpSatBackendError> {
    create_parent_dir(path)?;
    let temp_path = path.with_extension("pb.tmp");
    fs::write(&temp_path, request_bytes).map_err(|source| OrToolsCpSatBackendError::DumpIo {
        path: temp_path.clone(),
        source,
    })?;
    fs::rename(&temp_path, path).map_err(|source| OrToolsCpSatBackendError::DumpIo {
        path: path.to_path_buf(),
        source,
    })
}

fn write_summary_json(
    path: &Path,
    problem: &CompiledSelectorProblem,
    request: &wire::SelectorCpSatRequest,
    request_encoded_bytes: usize,
    dump_sequence: Option<usize>,
) -> Result<(), OrToolsCpSatBackendError> {
    create_parent_dir(path)?;
    let temp_path = path.with_extension("json.tmp");
    let mut file =
        fs::File::create(&temp_path).map_err(|source| OrToolsCpSatBackendError::DumpIo {
            path: temp_path.clone(),
            source,
        })?;
    let summary = problem_summary(problem, request, request_encoded_bytes, dump_sequence);
    serde_json::to_writer_pretty(&mut file, &summary).map_err(|source| {
        OrToolsCpSatBackendError::DumpSummaryJson {
            path: temp_path.clone(),
            source,
        }
    })?;
    file.write_all(b"\n")
        .map_err(|source| OrToolsCpSatBackendError::DumpIo {
            path: temp_path.clone(),
            source,
        })?;
    file.flush()
        .map_err(|source| OrToolsCpSatBackendError::DumpIo {
            path: temp_path.clone(),
            source,
        })?;
    drop(file);
    fs::rename(&temp_path, path).map_err(|source| OrToolsCpSatBackendError::DumpIo {
        path: path.to_path_buf(),
        source,
    })
}

fn create_parent_dir(path: &Path) -> Result<(), OrToolsCpSatBackendError> {
    if let Some(parent) = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
    {
        fs::create_dir_all(parent).map_err(|source| OrToolsCpSatBackendError::DumpIo {
            path: parent.to_path_buf(),
            source,
        })?;
    }
    Ok(())
}

fn dump_dir_path(dir: &Path, stem: &str, sequence: usize, extension: &str) -> PathBuf {
    dir.join(format!("{stem}-{sequence:06}.{extension}"))
}

fn dump_only_requested() -> bool {
    std::env::var_os(DUMP_ONLY_ENV)
        .map(|value| !value.is_empty() && value != "0")
        .unwrap_or(false)
}

fn problem_summary(
    problem: &CompiledSelectorProblem,
    request: &wire::SelectorCpSatRequest,
    request_encoded_bytes: usize,
    dump_sequence: Option<usize>,
) -> serde_json::Value {
    let total_domain_values = problem
        .variables
        .iter()
        .map(|variable| problem.variable_domain_value_count(variable))
        .sum::<usize>();
    let max_domain_values = problem
        .variables
        .iter()
        .map(|variable| problem.variable_domain_value_count(variable))
        .max()
        .unwrap_or(0);
    let allowed_row_count = problem
        .allowed_tuples
        .iter()
        .map(|constraint| problem.allowed_tuple_rows(constraint).len())
        .sum::<usize>();
    let allowed_cell_count = problem
        .allowed_tuples
        .iter()
        .map(|constraint| problem.allowed_tuple_rows(constraint).cell_count())
        .sum::<usize>();
    let shared_allowed_row_count = problem
        .allowed_tuple_row_sets
        .iter()
        .map(|row_set| row_set.rows.len())
        .sum::<usize>();
    let shared_allowed_cell_count = problem
        .allowed_tuple_row_sets
        .iter()
        .map(|row_set| row_set.rows.cell_count())
        .sum::<usize>();
    let shared_sparse_domain_value_count = problem
        .shared_variable_domains
        .iter()
        .map(|domain| domain.values.len())
        .sum::<usize>();
    let max_allowed_rows = problem
        .allowed_tuples
        .iter()
        .map(|constraint| problem.allowed_tuple_rows(constraint).len())
        .max()
        .unwrap_or(0);
    let max_allowed_arity = problem
        .allowed_tuples
        .iter()
        .map(|constraint| constraint.variables.len())
        .max()
        .unwrap_or(0);
    let binary_equal_count = problem
        .binary_constraints
        .iter()
        .filter(|constraint| matches!(constraint.kind, BinaryConstraintKind::Equal))
        .count();
    let binary_not_equal_count = problem
        .binary_constraints
        .iter()
        .filter(|constraint| matches!(constraint.kind, BinaryConstraintKind::NotEqual))
        .count();
    let binary_ordinal_before_count = problem
        .binary_constraints
        .iter()
        .filter(|constraint| matches!(constraint.kind, BinaryConstraintKind::OrdinalBefore))
        .count();
    let mut constraint_count_by_kind = BTreeMap::from([
        ("allowed_table", problem.allowed_tuples.len()),
        ("linear", problem.linear_constraints.len()),
        ("all_different", problem.all_different.len()),
    ]);
    for constraint in &problem.binary_constraints {
        let key = match constraint.kind {
            BinaryConstraintKind::Equal => "binary_equal",
            BinaryConstraintKind::NotEqual => "binary_not_equal",
            BinaryConstraintKind::OrdinalBefore => "binary_ordinal_before",
        };
        *constraint_count_by_kind.entry(key).or_insert(0) += 1;
    }
    let variable_count_by_domain = keyed_count(
        problem
            .variables
            .iter()
            .map(|variable| variable_domain_name(variable.domain)),
    );
    let domain_size_histogram = usize_histogram(
        problem
            .variables
            .iter()
            .map(|variable| problem.variable_domain_value_count(variable)),
    );
    let domain_size_histogram_by_domain =
        grouped_usize_histogram(problem.variables.iter().map(|variable| {
            (
                variable_domain_name(variable.domain),
                problem.variable_domain_value_count(variable),
            )
        }));
    let allowed_table_arity_histogram = usize_histogram(
        problem
            .allowed_tuples
            .iter()
            .map(|constraint| constraint.variables.len()),
    );
    let allowed_table_row_count_histogram = usize_histogram(
        problem
            .allowed_tuples
            .iter()
            .map(|constraint| problem.allowed_tuple_rows(constraint).len()),
    );
    let allowed_table_cell_count_histogram = usize_histogram(
        problem
            .allowed_tuples
            .iter()
            .map(|constraint| problem.allowed_tuple_rows(constraint).cell_count()),
    );
    let mut allowed_table_count_by_shape = BTreeMap::new();
    let mut allowed_table_logical_row_count_by_shape = BTreeMap::new();
    let mut allowed_table_logical_cell_count_by_shape = BTreeMap::new();
    let mut allowed_table_count_by_domain_signature = BTreeMap::new();
    let mut allowed_table_logical_cell_count_by_domain_signature = BTreeMap::new();
    for constraint in &problem.allowed_tuples {
        let shape = allowed_table_shape(problem, constraint);
        let row_count = problem.allowed_tuple_rows(constraint).len();
        let cell_count = problem.allowed_tuple_rows(constraint).cell_count();
        *allowed_table_count_by_shape.entry(shape).or_insert(0) += 1;
        *allowed_table_logical_row_count_by_shape
            .entry(shape)
            .or_insert(0) += row_count;
        *allowed_table_logical_cell_count_by_shape
            .entry(shape)
            .or_insert(0) += cell_count;

        let domain_signature = allowed_table_domain_signature(problem, constraint);
        *allowed_table_count_by_domain_signature
            .entry(domain_signature.clone())
            .or_insert(0) += 1;
        *allowed_table_logical_cell_count_by_domain_signature
            .entry(domain_signature)
            .or_insert(0) += cell_count;
    }
    let binary_constraint_count_by_kind = keyed_count(
        problem
            .binary_constraints
            .iter()
            .map(|constraint| binary_constraint_kind_name(constraint.kind)),
    );
    let all_different_arity_histogram = usize_histogram(
        problem
            .all_different
            .iter()
            .map(|constraint| constraint.variables.len()),
    );
    let all_different_count_by_reason = keyed_count(
        problem
            .all_different
            .iter()
            .map(|constraint| all_different_reason_name(&constraint.reason)),
    );
    let linear_constraint_arity_histogram = usize_histogram(
        problem
            .linear_constraints
            .iter()
            .map(|constraint| constraint.variables.len()),
    );
    let variable_domain_representation_count_by_kind = keyed_count(
        problem
            .variables
            .iter()
            .map(|variable| variable_domain_representation_name(&variable.values)),
    );
    let variable_domain_encoding_count_by_domain =
        grouped_keyed_count(problem.variables.iter().map(|variable| {
            (
                variable_domain_name(variable.domain),
                variable_domain_encoding_name(&variable.values),
            )
        }));
    let domain_sharing = variable_domain_sharing_summary(problem);

    let mut summary = serde_json::Map::new();
    macro_rules! field {
        ($name:literal, $value:expr) => {
            summary.insert($name.to_string(), serde_json::json!($value));
        };
    }

    field!("all_different_count", problem.all_different.len());
    field!(
        "all_different_count_by_reason",
        all_different_count_by_reason
    );
    field!(
        "all_different_arity_histogram",
        all_different_arity_histogram
    );
    field!("allowed_cell_count", allowed_cell_count);
    field!("shared_allowed_cell_count", shared_allowed_cell_count);
    field!("shared_allowed_row_count", shared_allowed_row_count);
    field!(
        "shared_sparse_domain_count",
        problem.shared_variable_domains.len()
    );
    field!(
        "shared_sparse_domain_value_count",
        shared_sparse_domain_value_count
    );
    field!(
        "allowed_row_set_count",
        problem.allowed_tuple_row_sets.len()
    );
    field!(
        "allowed_table_arity_histogram",
        allowed_table_arity_histogram
    );
    field!(
        "allowed_table_cell_count_histogram",
        allowed_table_cell_count_histogram
    );
    field!(
        "allowed_table_row_count_histogram",
        allowed_table_row_count_histogram
    );
    field!("allowed_table_count_by_shape", allowed_table_count_by_shape);
    field!(
        "allowed_table_logical_row_count_by_shape",
        allowed_table_logical_row_count_by_shape
    );
    field!(
        "allowed_table_logical_cell_count_by_shape",
        allowed_table_logical_cell_count_by_shape
    );
    field!(
        "allowed_table_count_by_domain_signature",
        allowed_table_count_by_domain_signature
    );
    field!(
        "allowed_table_logical_cell_count_by_domain_signature",
        allowed_table_logical_cell_count_by_domain_signature
    );
    field!("allowed_row_count", allowed_row_count);
    field!("allowed_table_count", problem.allowed_tuples.len());
    field!("binary_constraint_count", problem.binary_constraints.len());
    field!(
        "binary_constraint_count_by_kind",
        binary_constraint_count_by_kind
    );
    field!("binary_equal_count", binary_equal_count);
    field!("binary_not_equal_count", binary_not_equal_count);
    field!("binary_ordinal_before_count", binary_ordinal_before_count);
    field!("constraint_count_by_kind", constraint_count_by_kind);
    field!("domain_size_histogram", domain_size_histogram);
    field!(
        "domain_size_histogram_by_domain",
        domain_size_histogram_by_domain
    );
    field!("dump_sequence", dump_sequence);
    field!("linear_constraint_count", problem.linear_constraints.len());
    field!(
        "linear_constraint_arity_histogram",
        linear_constraint_arity_histogram
    );
    field!("max_allowed_arity", max_allowed_arity);
    field!("max_allowed_rows", max_allowed_rows);
    field!("max_domain_values", max_domain_values);
    field!("request_encoded_bytes", request_encoded_bytes);
    field!("request_proto_bytes", request_encoded_bytes);
    field!("target_projection_count", problem.target_projections.len());
    field!("total_domain_values", total_domain_values);
    field!(
        "variable_domain_encoding_count_by_domain",
        variable_domain_encoding_count_by_domain
    );
    field!(
        "variable_domain_representation_count_by_kind",
        variable_domain_representation_count_by_kind
    );
    field!("variable_domain_sharing", domain_sharing);
    field!(
        "value_dictionary_count",
        problem.value_dictionary.total_len()
    );
    field!("variable_count", problem.variables.len());
    field!("variable_count_by_domain", variable_count_by_domain);
    field!("wire_all_different_count", request.all_different.len());
    field!("wire_allowed_row_set_count", request.allowed_row_sets.len());
    field!("wire_allowed_table_count", request.allowed_tables.len());
    field!(
        "wire_binary_constraint_count",
        request.binary_constraints.len()
    );
    field!(
        "wire_linear_constraint_count",
        request.linear_constraints.len()
    );
    field!(
        "wire_target_projection_count",
        request.target_projections.len()
    );
    field!(
        "wire_shared_sparse_domain_count",
        request.shared_sparse_domains.len()
    );
    field!("wire_variable_count", request.variables.len());

    serde_json::Value::Object(summary)
}

fn allowed_table_shape(
    problem: &CompiledSelectorProblem,
    constraint: &CompiledAllowedTupleConstraint,
) -> &'static str {
    let mut source_matchish = false;
    let mut child_list_segment = false;
    let mut has_ast_node = false;
    let mut all_ast_node = true;
    let mut has_owner = false;
    let mut has_string = false;
    let mut has_statement_ordinal = false;

    for variable_id in &constraint.variables {
        let Some(variable) = problem.variables.get(variable_id.0) else {
            return "invalid_variable_reference";
        };
        let debug_name = variable.debug_name.as_deref().unwrap_or_default();
        source_matchish |= debug_name.contains("source_match")
            || debug_name.contains("anonymous_statement")
            || debug_name.starts_with("ast_child_list.segment");
        child_list_segment |= debug_name.starts_with("ast_child_list.segment");
        match variable.domain {
            VariableDomain::AstNode => has_ast_node = true,
            VariableDomain::Owner => {
                has_owner = true;
                all_ast_node = false;
            }
            VariableDomain::String => {
                has_string = true;
                all_ast_node = false;
            }
            VariableDomain::StatementOrdinal => {
                has_statement_ordinal = true;
                all_ast_node = false;
            }
        }
    }

    if source_matchish {
        if child_list_segment {
            "source_match_child_list_segment"
        } else if has_owner {
            "source_match_owner_projection"
        } else if has_statement_ordinal {
            "source_match_statement_ordinal"
        } else if has_string {
            "source_match_string_relation"
        } else if all_ast_node && has_ast_node {
            "source_match_ast_node_relation"
        } else {
            "source_match_other"
        }
    } else if has_owner && has_ast_node {
        "owner_ast_node_relation"
    } else if has_owner && has_string {
        "owner_string_relation"
    } else if has_owner {
        "owner_relation"
    } else if has_ast_node && has_string {
        "ast_node_string_relation"
    } else if all_ast_node && has_ast_node {
        "ast_node_relation"
    } else {
        "non_source_match_other"
    }
}

fn allowed_table_domain_signature(
    problem: &CompiledSelectorProblem,
    constraint: &CompiledAllowedTupleConstraint,
) -> String {
    let mut signature = String::new();
    for (index, variable_id) in constraint.variables.iter().enumerate() {
        if index > 0 {
            signature.push(',');
        }
        let domain = problem
            .variables
            .get(variable_id.0)
            .map(|variable| variable_domain_name(variable.domain))
            .unwrap_or("invalid");
        signature.push_str(domain);
    }
    signature
}

fn variable_domain_sharing_summary(problem: &CompiledSelectorProblem) -> serde_json::Value {
    let mut domain_use_counts: BTreeMap<
        (&'static str, VariableDomainUseKey),
        VariableDomainUseStats,
    > = BTreeMap::new();
    let mut domain_use_counts_by_domain: BTreeMap<
        &'static str,
        BTreeMap<VariableDomainUseKey, VariableDomainUseStats>,
    > = BTreeMap::new();
    for variable in &problem.variables {
        let domain = variable_domain_name(variable.domain);
        let key = variable_domain_use_key(variable);
        let value_count = problem.variable_domain_value_count(variable);
        domain_use_counts
            .entry((domain, key.clone()))
            .or_insert(VariableDomainUseStats {
                value_count,
                use_count: 0,
            })
            .use_count += 1;
        domain_use_counts_by_domain
            .entry(domain)
            .or_default()
            .entry(key)
            .or_insert(VariableDomainUseStats {
                value_count,
                use_count: 0,
            })
            .use_count += 1;
    }

    let by_domain = domain_use_counts_by_domain
        .iter()
        .map(|(domain, counts)| {
            (
                *domain,
                domain_sharing_stats(
                    counts
                        .values()
                        .map(|stats| (stats.value_count, stats.use_count)),
                ),
            )
        })
        .collect::<BTreeMap<_, _>>();
    let mut summary = domain_sharing_stats(
        domain_use_counts
            .iter()
            .map(|((_domain, _key), stats)| (stats.value_count, stats.use_count)),
    );
    summary
        .as_object_mut()
        .expect("domain sharing stats should be a JSON object")
        .insert("by_domain".to_string(), serde_json::json!(by_domain));
    summary
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
enum VariableDomainUseKey {
    Full,
    SparseExact(Vec<BackendValueId>),
    SparseFingerprint { len: usize, hash: u64 },
    SharedSparse(usize),
}

#[derive(Debug, Clone, Copy)]
struct VariableDomainUseStats {
    value_count: usize,
    use_count: usize,
}

fn variable_domain_use_key(variable: &CompiledVariable) -> VariableDomainUseKey {
    match &variable.values {
        CompiledVariableDomain::Full(_) => VariableDomainUseKey::Full,
        CompiledVariableDomain::Sparse(values)
            if values.len() <= DOMAIN_SHARING_EXACT_SPARSE_LIMIT =>
        {
            VariableDomainUseKey::SparseExact(values.clone())
        }
        CompiledVariableDomain::Sparse(values) => {
            let mut hasher = std::collections::hash_map::DefaultHasher::new();
            values.hash(&mut hasher);
            VariableDomainUseKey::SparseFingerprint {
                len: values.len(),
                hash: hasher.finish(),
            }
        }
        CompiledVariableDomain::SharedSparse(id) => VariableDomainUseKey::SharedSparse(id.0),
    }
}

fn domain_sharing_stats(
    domain_value_use_counts: impl IntoIterator<Item = (usize, usize)>,
) -> serde_json::Value {
    let mut unique_domain_count = 0;
    let mut unique_domain_value_count = 0;
    let mut total_variable_domain_values = 0;
    let mut shared_domain_group_count = 0;
    let mut max_variables_sharing_domain = 0;
    let mut variables_per_unique_domain = Vec::new();

    for (value_count, use_count) in domain_value_use_counts {
        unique_domain_count += 1;
        unique_domain_value_count += value_count;
        total_variable_domain_values += value_count * use_count;
        if use_count > 1 {
            shared_domain_group_count += 1;
        }
        max_variables_sharing_domain = max_variables_sharing_domain.max(use_count);
        variables_per_unique_domain.push(use_count);
    }

    serde_json::json!({
        "current_encoded_value_count": total_variable_domain_values,
        "deduplicated_encoded_value_count": unique_domain_value_count,
        "encoded_value_savings_if_deduplicated": total_variable_domain_values.saturating_sub(unique_domain_value_count),
        "max_variables_sharing_domain": max_variables_sharing_domain,
        "shared_domain_group_count": shared_domain_group_count,
        "unique_domain_count": unique_domain_count,
        "variables_per_unique_domain_histogram": usize_histogram(variables_per_unique_domain),
    })
}

fn usize_histogram(values: impl IntoIterator<Item = usize>) -> BTreeMap<String, usize> {
    let mut histogram = BTreeMap::new();
    for value in values {
        *histogram.entry(value.to_string()).or_insert(0) += 1;
    }
    histogram
}

fn grouped_usize_histogram(
    values: impl IntoIterator<Item = (&'static str, usize)>,
) -> BTreeMap<&'static str, BTreeMap<String, usize>> {
    let mut grouped = BTreeMap::new();
    for (key, value) in values {
        *grouped
            .entry(key)
            .or_insert_with(BTreeMap::new)
            .entry(value.to_string())
            .or_insert(0) += 1;
    }
    grouped
}

fn grouped_keyed_count(
    values: impl IntoIterator<Item = (&'static str, &'static str)>,
) -> BTreeMap<&'static str, BTreeMap<&'static str, usize>> {
    let mut grouped = BTreeMap::new();
    for (group, key) in values {
        *grouped
            .entry(group)
            .or_insert_with(BTreeMap::new)
            .entry(key)
            .or_insert(0) += 1;
    }
    grouped
}

fn keyed_count(keys: impl IntoIterator<Item = &'static str>) -> BTreeMap<&'static str, usize> {
    let mut counts = BTreeMap::new();
    for key in keys {
        *counts.entry(key).or_insert(0) += 1;
    }
    counts
}

fn variable_domain_name(domain: VariableDomain) -> &'static str {
    match domain {
        VariableDomain::Owner => "owner",
        VariableDomain::AstNode => "ast_node",
        VariableDomain::String => "string",
        VariableDomain::StatementOrdinal => "statement_ordinal",
    }
}

fn variable_domain_representation_name(values: &CompiledVariableDomain) -> &'static str {
    match values {
        CompiledVariableDomain::Full(_) => "full",
        CompiledVariableDomain::Sparse(_) => "sparse",
        CompiledVariableDomain::SharedSparse(_) => "shared_sparse",
    }
}

fn variable_domain_encoding_name(values: &CompiledVariableDomain) -> &'static str {
    match values {
        CompiledVariableDomain::Full(_) => "dense",
        CompiledVariableDomain::Sparse(_) => "sparse",
        CompiledVariableDomain::SharedSparse(_) => "shared_sparse",
    }
}

fn binary_constraint_kind_name(kind: BinaryConstraintKind) -> &'static str {
    match kind {
        BinaryConstraintKind::Equal => "equal",
        BinaryConstraintKind::NotEqual => "not_equal",
        BinaryConstraintKind::OrdinalBefore => "ordinal_before",
    }
}

fn all_different_reason_name(reason: &AllDifferentReason) -> &'static str {
    match reason {
        AllDifferentReason::TargetInjectivity { .. } => "target_injectivity",
        AllDifferentReason::SelectorSemantics { .. } => "selector_semantics",
    }
}

fn request_from_problem(
    problem: &CompiledSelectorProblem,
) -> Result<wire::SelectorCpSatRequest, OrToolsCpSatBackendError> {
    Ok(wire::SelectorCpSatRequest {
        shared_sparse_domains: problem
            .shared_variable_domains
            .iter()
            .map(shared_sparse_domain_from_backend)
            .collect::<Result<Vec<_>, _>>()?,
        variables: problem
            .variables
            .iter()
            .map(|variable| variable_from_backend(problem, variable))
            .collect::<Result<Vec<_>, _>>()?,
        allowed_row_sets: problem
            .allowed_tuple_row_sets
            .iter()
            .map(row_set_from_backend)
            .collect::<Result<Vec<_>, _>>()?,
        allowed_tables: problem
            .allowed_tuples
            .iter()
            .map(table_from_backend)
            .collect::<Result<Vec<_>, _>>()?,
        binary_constraints: problem
            .binary_constraints
            .iter()
            .map(binary_constraint_from_backend)
            .collect::<Result<Vec<_>, _>>()?,
        linear_constraints: problem
            .linear_constraints
            .iter()
            .map(linear_constraint_from_backend)
            .collect::<Result<Vec<_>, _>>()?,
        all_different: problem
            .all_different
            .iter()
            .map(all_different_from_backend)
            .collect::<Result<Vec<_>, _>>()?,
        target_projections: problem
            .target_projections
            .iter()
            .map(target_projection_from_backend)
            .collect::<Result<Vec<_>, _>>()?,
    })
}

fn variable_from_backend(
    problem: &CompiledSelectorProblem,
    variable: &CompiledVariable,
) -> Result<wire::Variable, OrToolsCpSatBackendError> {
    let domain = match &variable.values {
        CompiledVariableDomain::Full(domain) => {
            Some(wire::variable::Domain::DenseDomain(wire::DenseDomain {
                value_count: u32_id(
                    "variables.dense_domain.value_count",
                    problem.full_domains.get(*domain).len(),
                )?,
            }))
        }
        CompiledVariableDomain::Sparse(values) => {
            Some(wire::variable::Domain::SparseDomain(wire::SparseDomain {
                values: values.iter().map(|value| value.0).collect(),
            }))
        }
        CompiledVariableDomain::SharedSparse(id) => {
            let shared_domain = problem.shared_variable_domain(*id).ok_or_else(|| {
                OrToolsCpSatBackendError::InvalidProblem(format!(
                    "variable {:?} references unknown shared sparse domain {:?}",
                    variable.id, id
                ))
            })?;
            Some(wire::variable::Domain::SharedSparseDomainId(u32_id(
                "variables.shared_sparse_domain_id",
                shared_domain.id.0,
            )?))
        }
    };
    Ok(wire::Variable {
        id: constraint_variable_id(variable.id)?,
        debug_name: variable.debug_name.clone().unwrap_or_default(),
        domain,
    })
}

fn shared_sparse_domain_from_backend(
    domain: &selector_constraint_backend::CompiledSharedVariableDomain,
) -> Result<wire::SharedSparseDomain, OrToolsCpSatBackendError> {
    Ok(wire::SharedSparseDomain {
        id: u32_id("shared_sparse_domains.id", domain.id.0)?,
        values: domain.values.iter().map(|value| value.0).collect(),
    })
}

fn table_from_backend(
    constraint: &CompiledAllowedTupleConstraint,
) -> Result<wire::TableConstraint, OrToolsCpSatBackendError> {
    Ok(wire::TableConstraint {
        id: u32_id("allowed_tables.id", constraint.id.0)?,
        variable_ids: constraint
            .variables
            .iter()
            .copied()
            .map(constraint_variable_id)
            .collect::<Result<Vec<_>, _>>()?,
        allowed_rows: Vec::new(),
        row_set_id: Some(u32_id("allowed_tables.row_set_id", constraint.row_set.0)?),
    })
}

fn row_set_from_backend(
    row_set: &selector_constraint_backend::CompiledAllowedTupleRowSet,
) -> Result<wire::AllowedRowSet, OrToolsCpSatBackendError> {
    Ok(wire::AllowedRowSet {
        id: u32_id("allowed_row_sets.id", row_set.id.0)?,
        arity: u32_id("allowed_row_sets.arity", row_set.rows.arity())?,
        values: row_set.rows.values().iter().map(|value| value.0).collect(),
    })
}

fn binary_constraint_from_backend(
    constraint: &CompiledBinaryConstraint,
) -> Result<wire::BinaryConstraint, OrToolsCpSatBackendError> {
    Ok(wire::BinaryConstraint {
        left_variable_id: constraint_variable_id(constraint.left)?,
        right_variable_id: constraint_variable_id(constraint.right)?,
        kind: match constraint.kind {
            BinaryConstraintKind::Equal => wire::BinaryConstraintKind::Equal,
            BinaryConstraintKind::NotEqual => wire::BinaryConstraintKind::NotEqual,
            BinaryConstraintKind::OrdinalBefore => wire::BinaryConstraintKind::OrdinalBefore,
        } as i32,
    })
}

fn linear_constraint_from_backend(
    constraint: &CompiledLinearConstraint,
) -> Result<wire::LinearConstraint, OrToolsCpSatBackendError> {
    Ok(wire::LinearConstraint {
        variable_ids: constraint
            .variables
            .iter()
            .copied()
            .map(constraint_variable_id)
            .collect::<Result<Vec<_>, _>>()?,
        coefficients: constraint.coefficients.clone(),
        offset: constraint.offset,
        domain: constraint.domain.clone(),
    })
}

fn all_different_from_backend(
    constraint: &CompiledAllDifferentConstraint,
) -> Result<wire::AllDifferent, OrToolsCpSatBackendError> {
    Ok(wire::AllDifferent {
        id: u32_id("all_different.id", constraint.id.0)?,
        variable_ids: constraint
            .variables
            .iter()
            .copied()
            .map(constraint_variable_id)
            .collect::<Result<Vec<_>, _>>()?,
    })
}

fn target_projection_from_backend(
    projection: &TargetProjection,
) -> Result<wire::TargetProjection, OrToolsCpSatBackendError> {
    let binding_projection = match &projection.binding_projection {
        Some(TargetBindingProjection::Variable(variable)) => Some(
            wire::target_projection::BindingProjection::BindingVariableId(constraint_variable_id(
                *variable,
            )?),
        ),
        Some(TargetBindingProjection::Const(binding)) => Some(
            wire::target_projection::BindingProjection::BindingConst(binding.clone()),
        ),
        None => None,
    };
    Ok(wire::TargetProjection {
        target_id: u32_id("target_projections.target_id", projection.target.0)?,
        owner_variable_id: constraint_variable_id(projection.owner_variable)?,
        binding_projection,
    })
}

fn response_into_backend_result(
    response: wire::SelectorCpSatResponse,
) -> Result<BackendSolveResult, OrToolsCpSatBackendError> {
    let status_code = response.status;
    let diagnostic = (!response.diagnostic.is_empty()).then_some(response.diagnostic);
    let solver_response_stats =
        (!response.solver_response_stats.is_empty()).then_some(response.solver_response_stats);
    let solver_status = match wire::SolverStatus::try_from(status_code) {
        Ok(status) => status,
        Err(_) => {
            return Err(OrToolsCpSatBackendError::InvalidStatus {
                status: status_code,
                diagnostic,
            });
        }
    };
    let status = match solver_status {
        wire::SolverStatus::Unsatisfiable => BackendSolveStatus::Unsatisfiable,
        wire::SolverStatus::Satisfiable => BackendSolveStatus::Satisfiable,
        wire::SolverStatus::Ambiguous => BackendSolveStatus::Ambiguous,
        wire::SolverStatus::Unknown => BackendSolveStatus::Unknown,
        wire::SolverStatus::Invalid | wire::SolverStatus::Unspecified => {
            return Err(OrToolsCpSatBackendError::InvalidStatus {
                status: status_code,
                diagnostic,
            });
        }
    };
    let assignment_coverage = match wire::AssignmentCoverage::try_from(response.assignment_coverage)
        .map_err(|_| OrToolsCpSatBackendError::InvalidAssignmentCoverage {
            coverage: response.assignment_coverage,
        })? {
        wire::AssignmentCoverage::Unspecified | wire::AssignmentCoverage::Sample => {
            BackendAssignmentCoverage::Sample
        }
        wire::AssignmentCoverage::TargetSupportComplete => {
            BackendAssignmentCoverage::TargetSupportComplete
        }
    };
    Ok(BackendSolveResult {
        status,
        assignment_coverage,
        assignments: response
            .assignments
            .into_iter()
            .map(assignment_row_into_backend)
            .collect(),
        diagnostic,
        solver_response_stats,
    })
}

fn assignment_row_into_backend(row: wire::AssignmentRow) -> BackendAssignment {
    BackendAssignment {
        values: row
            .values
            .into_iter()
            .map(|assignment| BackendVariableAssignment {
                variable: ConstraintVariableId(assignment.variable_id as usize),
                value: BackendValueId(assignment.value),
            })
            .collect(),
    }
}

fn constraint_variable_id(id: ConstraintVariableId) -> Result<u32, OrToolsCpSatBackendError> {
    u32_id("variable id", id.0)
}

fn u32_id(field: &'static str, value: usize) -> Result<u32, OrToolsCpSatBackendError> {
    value
        .try_into()
        .map_err(|_| OrToolsCpSatBackendError::IdOutOfRange { field, value })
}

