    #[test]
    fn cpsat_sidecar_resolves_broad_specific_target_injectivity() {
        let mut program = SelectorProgram::default();
        let broad_owner = program.add_variable(VariableDomain::Owner, Some("broad".to_string()));
        let strict_owner = program.add_variable(VariableDomain::Owner, Some("strict".to_string()));
        let broad_target = program.add_target(
            ChunkId(0),
            broad_owner,
            "module",
            ClaimKind::Binding {
                export_name: Some("Broad".to_string()),
            },
            ClaimOrigin::Synthetic,
        );
        let strict_target = program.add_target(
            ChunkId(0),
            strict_owner,
            "module",
            ClaimKind::Binding {
                export_name: Some("Strict".to_string()),
            },
            ClaimOrigin::Synthetic,
        );
        program.add_atom(SelectorAtom::OwnerDeclaresBinding {
            owner: OwnerTerm::Var { id: broad_owner },
            binding: StringTerm::Const {
                value: "shared".to_string(),
            },
        });
        program.add_atom(SelectorAtom::OwnerDeclaresBinding {
            owner: OwnerTerm::Var { id: strict_owner },
            binding: StringTerm::Const {
                value: "specific".to_string(),
            },
        });
        program.require_all_different(vec![broad_target, strict_target]);

        let mut facts = SelectorFactStore::default();
        facts.push(owner_fact(10, 0, "var"));
        facts.push(owner_fact(20, 1, "var"));
        facts.push(declared_binding(10, "shared"));
        facts.push(declared_binding(20, "shared"));
        facts.push(declared_binding(20, "specific"));

        let backend = OrToolsCpSatBackend::new(sidecar_path());
        let result = solve_with_backend(&program, &facts, &backend).unwrap();

        assert_eq!(
            result.outcome_for(broad_target),
            Some(&ClaimOutcome::Unique {
                claim: ResolvedClaim {
                    chunk_id: ChunkId(0),
                    owner: OwnerId(10),
                    statement_ordinal: StatementOrdinal(0),
                    binding: Some("shared".to_string()),
                    provenance: Vec::new(),
                }
            })
        );
        assert_eq!(
            result.outcome_for(strict_target),
            Some(&ClaimOutcome::Unique {
                claim: ResolvedClaim {
                    chunk_id: ChunkId(0),
                    owner: OwnerId(20),
                    statement_ordinal: StatementOrdinal(1),
                    binding: Some("specific".to_string()),
                    provenance: Vec::new(),
                }
            })
        );
    }

    #[test]
    fn cpsat_sidecar_resolves_alpha_all_binding_group_multideclarator() {
        js_ast::with_swc_globals(|| {
            let mut group_selector = AnonymousStatementSelector::exact(
                "const primary = EXPR_PRIMARY, secondary = EXPR_SECONDARY;",
            );
            group_selector.identifiers = SourceMatchIdentifierMode::AlphaAll;
            let mut primary_selector = group_selector.clone();
            primary_selector.target_binding = Some("primary".to_string());
            let mut secondary_selector = group_selector.clone();
            secondary_selector.target_binding = Some("secondary".to_string());

            let mut builder = MemberSelectorProgramBuilder::new(
                MemberSelectorLoweringContext::new(ChunkId(0), "static/app::settings"),
            );
            let primary_target = builder
                .declare_member_target_in_module(
                    "static/app::settings",
                    "primary",
                    &MemberSelectorSpec::SourceMatch(primary_selector),
                )
                .unwrap();
            let secondary_target = builder
                .declare_member_target_in_module(
                    "static/app::settings",
                    "secondary",
                    &MemberSelectorSpec::SourceMatch(secondary_selector),
                )
                .unwrap();
            assert!(
                builder
                    .try_lower_native_source_match_group(
                        "static/app::settings",
                        &group_selector,
                        &BTreeMap::from([
                            ("primary".to_string(), "primary".to_string()),
                            ("secondary".to_string(), "secondary".to_string()),
                        ]),
                    )
                    .unwrap()
            );
            let program = builder.into_program().unwrap();

            let module = js_ast::parse_js_module_ast(
                "<chunk>",
                "const primary = 10, secondary = 20;\n\
                 console.log(primary + secondary);\n\
                 export { primary, secondary };\n",
            )
            .unwrap();
            let chunk_facts = chunk_facts::extract_facts(&module).unwrap();
            let analysis =
                analysis::facts::analyze_chunk(&module, &AnalysisHints::default(), None, |_| None);
            let owner_graph = analysis::graph::build_owner_graph(&analysis.facts).unwrap();
            let mut facts = SelectorFactStore::default();
            facts.extend_chunk_facts(ChunkId(0), &chunk_facts);
            for node in owner_graph.iter_nodes() {
                facts.push(SelectorFact::Owner {
                    chunk_id: ChunkId(0),
                    owner: node.id,
                    statement_ordinal: node.statement_ordinal,
                    statement_kind: node.kind.to_string(),
                });
                for binding in &node.declared {
                    facts.push(SelectorFact::DeclaredBinding {
                        chunk_id: ChunkId(0),
                        owner: node.id,
                        binding: binding.0.as_str().to_string(),
                        export_name: None,
                    });
                }
            }
            for edge in owner_graph.iter_edges() {
                if let Some(binding) = edge.reason.binding() {
                    facts.push(SelectorFact::OwnerReferencesBinding {
                        chunk_id: ChunkId(0),
                        owner: edge.from,
                        binding: binding.0.as_str().to_string(),
                        edge_kind: edge.reason.kind().to_string(),
                    });
                }
            }

            let backend = OrToolsCpSatBackend::new(sidecar_path());
            let result = solve_with_backend(&program, &facts, &backend).unwrap();

            assert_eq!(
                result.outcome_for(primary_target),
                Some(&ClaimOutcome::Unique {
                    claim: ResolvedClaim {
                        chunk_id: ChunkId(0),
                        owner: OwnerId(0),
                        statement_ordinal: StatementOrdinal(0),
                        binding: Some("primary".to_string()),
                        provenance: Vec::new(),
                    }
                })
            );
            assert_eq!(
                result.outcome_for(secondary_target),
                Some(&ClaimOutcome::Unique {
                    claim: ResolvedClaim {
                        chunk_id: ChunkId(0),
                        owner: OwnerId(1),
                        statement_ordinal: StatementOrdinal(1),
                        binding: Some("secondary".to_string()),
                        provenance: Vec::new(),
                    }
                })
            );
        });
    }

    #[test]
    fn cpsat_sidecar_resolves_alpha_target_binding_with_multideclarator_context() {
        js_ast::with_swc_globals(|| {
            let mut selector = AnonymousStatementSelector::exact(
                r#"const config = { kind: "selected", enabled: true };
function readConfig() {
  return config.kind;
}"#,
            );
            selector.identifiers = SourceMatchIdentifierMode::AlphaAll;
            selector.target_binding = Some("config".to_string());
            let lowered = selector_ir_lowering::lower_member_selector(
                &MemberSelectorLoweringContext::new(ChunkId(0), "static/app::selected_config"),
                "selectedConfig",
                &MemberSelectorSpec::SourceMatch(selector),
            )
            .unwrap();
            let facts = selector_fact_store_from_source(
                r#"const helperBinding = { kind: "helper" },
  runtimeBinding = { kind: "selected", enabled: true },
  trailingBinding = { kind: "trailing" };
function runtimeReader() {
  return runtimeBinding.kind;
}
console.log(runtimeReader(), helperBinding.kind, trailingBinding.kind);
export { helperBinding, runtimeBinding, trailingBinding, runtimeReader };
"#,
            );

            let backend = OrToolsCpSatBackend::new(sidecar_path());
            let result = solve_with_backend(&lowered.program, &facts, &backend).unwrap();
            let owner = owner_for_binding(&facts, "runtimeBinding");

            assert_eq!(
                result.outcome_for(lowered.target),
                Some(&ClaimOutcome::Unique {
                    claim: ResolvedClaim {
                        chunk_id: ChunkId(0),
                        owner,
                        statement_ordinal: statement_ordinal_for_owner(&facts, owner),
                        binding: Some("runtimeBinding".to_string()),
                        provenance: Vec::new(),
                    }
                })
            );
        });
    }

    #[test]
    fn cpsat_sidecar_solves_cross_ref_anchor_in_one_program() {
        let mut program = SelectorProgram::default();
        let anchor_owner = program.add_variable(VariableDomain::Owner, Some("anchor".to_string()));
        let delegator_owner =
            program.add_variable(VariableDomain::Owner, Some("delegator".to_string()));
        let anchor_target = program.add_target(
            ChunkId(0),
            anchor_owner,
            "module",
            ClaimKind::Binding {
                export_name: Some("Anchor".to_string()),
            },
            ClaimOrigin::Synthetic,
        );
        let delegator_target = program.add_target(
            ChunkId(0),
            delegator_owner,
            "module",
            ClaimKind::Binding {
                export_name: Some("Delegator".to_string()),
            },
            ClaimOrigin::Synthetic,
        );
        program.add_atom(SelectorAtom::OwnerDeclaresBinding {
            owner: OwnerTerm::Var { id: anchor_owner },
            binding: StringTerm::Const {
                value: "a".to_string(),
            },
        });
        program.add_atom(SelectorAtom::OwnerReferencesOwner {
            owner: OwnerTerm::Var {
                id: delegator_owner,
            },
            referenced: OwnerTerm::Var { id: anchor_owner },
        });
        program.add_atom(SelectorAtom::OwnerKind {
            owner: OwnerTerm::Var {
                id: delegator_owner,
            },
            statement_kind: StringTerm::Const {
                value: "fn_decl".to_string(),
            },
        });
        program.require_all_different(vec![anchor_target, delegator_target]);

        let mut facts = SelectorFactStore::default();
        facts.push(owner_fact(1, 1, "var_decl"));
        facts.push(declared_binding(1, "a"));
        facts.push(owner_fact(2, 2, "fn_decl"));
        facts.push(declared_binding(2, "b"));
        facts.push(owner_references_binding(2, "a"));
        facts.push(owner_fact(3, 3, "fn_decl"));
        facts.push(declared_binding(3, "other"));
        facts.push(owner_references_binding(3, "missing"));

        let backend = OrToolsCpSatBackend::new(sidecar_path());
        let result = solve_with_backend(&program, &facts, &backend).unwrap();

        assert_eq!(
            result.outcome_for(anchor_target),
            Some(&ClaimOutcome::Unique {
                claim: ResolvedClaim {
                    chunk_id: ChunkId(0),
                    owner: OwnerId(1),
                    statement_ordinal: StatementOrdinal(1),
                    binding: Some("a".to_string()),
                    provenance: Vec::new(),
                }
            })
        );
        assert_eq!(
            result.outcome_for(delegator_target),
            Some(&ClaimOutcome::Unique {
                claim: ResolvedClaim {
                    chunk_id: ChunkId(0),
                    owner: OwnerId(2),
                    statement_ordinal: StatementOrdinal(2),
                    binding: Some("b".to_string()),
                    provenance: Vec::new(),
                }
            })
        );
    }

    #[test]
    fn cpsat_sidecar_solves_object_constrained_reads_member_jointly() {
        let mut program = SelectorProgram::default();
        let object_owner = program.add_variable(VariableDomain::Owner, Some("object".to_string()));
        let reader_owner = program.add_variable(VariableDomain::Owner, Some("reader".to_string()));
        let object_target = program.add_target(
            ChunkId(0),
            object_owner,
            "module",
            ClaimKind::Binding {
                export_name: Some("Context".to_string()),
            },
            ClaimOrigin::Synthetic,
        );
        let reader_target = program.add_target(
            ChunkId(0),
            reader_owner,
            "module",
            ClaimKind::Binding {
                export_name: Some("ReadId".to_string()),
            },
            ClaimOrigin::Synthetic,
        );
        program.add_atom(SelectorAtom::OwnerDeclaresBinding {
            owner: OwnerTerm::Var { id: object_owner },
            binding: StringTerm::Const {
                value: "ctx".to_string(),
            },
        });
        program.add_atom(SelectorAtom::ReadsMemberOfOwner {
            owner: OwnerTerm::Var { id: reader_owner },
            object: OwnerTerm::Var { id: object_owner },
            member: StringTerm::Const {
                value: "id".to_string(),
            },
        });
        program.add_atom(SelectorAtom::OwnerKind {
            owner: OwnerTerm::Var { id: reader_owner },
            statement_kind: StringTerm::Const {
                value: "fn_decl".to_string(),
            },
        });
        program.require_all_different(vec![object_target, reader_target]);

        let mut facts = SelectorFactStore::default();
        facts.push(owner_fact(1, 1, "var_decl"));
        facts.push(declared_binding(1, "ctx"));
        facts.push(owner_fact(2, 2, "fn_decl"));
        facts.push(declared_binding(2, "readId"));
        facts.push(member_read(2, Some("ctx"), "id"));
        facts.push(owner_fact(3, 3, "fn_decl"));
        facts.push(declared_binding(3, "other"));
        facts.push(member_read(3, Some("otherCtx"), "id"));

        let backend = OrToolsCpSatBackend::new(sidecar_path());
        let result = solve_with_backend(&program, &facts, &backend).unwrap();

        assert_eq!(
            result.outcome_for(object_target),
            Some(&ClaimOutcome::Unique {
                claim: ResolvedClaim {
                    chunk_id: ChunkId(0),
                    owner: OwnerId(1),
                    statement_ordinal: StatementOrdinal(1),
                    binding: Some("ctx".to_string()),
                    provenance: Vec::new(),
                }
            })
        );
        assert_eq!(
            result.outcome_for(reader_target),
            Some(&ClaimOutcome::Unique {
                claim: ResolvedClaim {
                    chunk_id: ChunkId(0),
                    owner: OwnerId(2),
                    statement_ordinal: StatementOrdinal(2),
                    binding: Some("readId".to_string()),
                    provenance: Vec::new(),
                }
            })
        );
    }

